<script setup lang="ts">
import {ref,onBeforeUnmount} from 'vue';
import {metadata} from '../services/metadata';
const props=defineProps<{assetIds:string[]}>();
type Status={status:string;total:number;processed:number;hashed:number;failed:number;canceled:number;needsRecovery:boolean;items:{fileId:string;status:string;errorCode:string|null}[];next_cursor:string|null};
type Group={sha256:string;size:number;fileCount:number;files:{fileId:string;name:string;logicalAssetIds:string[];logicalAssetCount:number}[]};
const jobs=ref<{id:string;status:string;total:number}[]>([]),details=ref<Status['items']>([]),detailCursor=ref<string|null>(null);
const busy=ref(false),jobId=ref(''),status=ref<Status>(),message=ref(''),groups=ref<Group[]>([]),groupCursor=ref<string|null>(null),fileCursor=ref<string|null>(null),queryCursor=ref<string|null>(null),stale=ref(0);let alive=true,polling=false,timer:ReturnType<typeof setInterval>|undefined;
onBeforeUnmount(()=>{alive=false;if(timer)clearInterval(timer);});
async function poll(){if(!jobId.value||polling)return;polling=true;try{const result=await metadata<Status>('duplicates.status',{job_id:jobId.value,after_id:null});if(!alive)return;status.value=result;details.value=result.items??[];detailCursor.value=result.next_cursor??null;if(!['queued','running'].includes(result.status)||result.needsRecovery){if(timer)clearInterval(timer);}}catch{if(alive)message.value='해시 작업 상태를 조회하지 못했습니다.';}finally{polling=false;}}
async function start(){if(busy.value||!props.assetIds.length||props.assetIds.length>100)return;busy.value=true;message.value='';try{const result=await metadata<{jobId:string}>('duplicates.start',{asset_ids:[...props.assetIds],confirmed:true});if(!alive)return;jobId.value=result.jobId;groups.value=[];status.value=undefined;queryCursor.value=null;groupCursor.value=null;fileCursor.value=null;await poll();const current=status.value as Status|undefined;if(alive&&current&&['queued','running'].includes(current.status)&&!current.needsRecovery)timer=setInterval(()=>void poll(),500);}catch{if(alive)message.value='해시 작업을 시작하지 못했습니다. 선택·기존 작업·파일 한도를 확인하세요.';}finally{busy.value=false;}}
async function list(){if(busy.value)return;busy.value=true;try{const result=await metadata<{items:typeof jobs.value}>('duplicates.list',{});if(alive)jobs.value=result.items;}catch{if(alive)message.value='저장된 해시 작업을 불러오지 못했습니다.';}finally{busy.value=false;}}
async function track(id:string){if(timer)clearInterval(timer);jobId.value=id;groups.value=[];await poll();const current=status.value as Status|undefined;if(alive&&current&&['queued','running'].includes(current.status)&&!current.needsRecovery)timer=setInterval(()=>void poll(),500);}
async function moreDetails(){if(busy.value||!detailCursor.value)return;busy.value=true;try{const result=await metadata<Status>('duplicates.status',{job_id:jobId.value,after_id:detailCursor.value});if(alive){details.value.push(...result.items);detailCursor.value=result.next_cursor;}}catch{if(alive)message.value='파일별 해시 상태를 조회하지 못했습니다.';}finally{busy.value=false;}}
async function cancel(){if(busy.value||!jobId.value)return;busy.value=true;try{await metadata('duplicates.cancel',{job_id:jobId.value});if(alive){message.value='취소를 요청했습니다. 저장된 성공 해시는 유지합니다.';await poll();}}catch{if(alive)message.value='취소 요청에 실패했습니다.';}finally{busy.value=false;}}
async function compare(more=false){if(busy.value||!jobId.value)return;busy.value=true;try{if(!more){queryCursor.value=null;groupCursor.value=null;fileCursor.value=null;groups.value=[];}else if(!fileCursor.value)queryCursor.value=groupCursor.value;
 const result=await metadata<{items:Group[];next_cursor:string|null;next_file_cursor:string|null;staleCount:number}>('duplicates.candidates',{job_id:jobId.value,after_hash:queryCursor.value,after_file_id:fileCursor.value});if(!alive)return;
 for(const group of result.items){const old=groups.value.find(g=>g.sha256===group.sha256);if(old){for(const file of group.files)if(!old.files.some(f=>f.fileId===file.fileId))old.files.push(file);}else groups.value.push(group);}
 groupCursor.value=result.next_cursor;fileCursor.value=result.next_file_cursor;stale.value=result.staleCount;message.value=groups.value.length?'같은 SHA-256·크기의 후보입니다. 논리 에셋·구매 권리의 동일성을 뜻하지 않습니다.':'현재 검증된 중복 후보가 없습니다.';
 }catch{if(alive)message.value='후보 비교에 실패했습니다. 파일 상태가 바뀌었다면 다시 계산하세요.';}finally{busy.value=false;}}
</script>
<template><details class="duplicate-candidates"><summary>동일 내용 파일 후보</summary><p>선택한 에셋의 고유 구성 파일 최대100개·파일당1GiB를 명시적으로 SHA-256 계산합니다. AI 호출·자동 병합·삭제는 하지 않습니다.</p><button type="button" :disabled="busy" @click="list">저장된 해시 작업 조회</button><ul><li v-for="job in jobs" :key="job.id"><button type="button" :disabled="busy" @click="track(job.id)">{{job.status}} · {{job.total}}파일 · {{job.id}}</button></li></ul><button type="button" :disabled="busy||!assetIds.length||assetIds.length>100||(!!status&&['queued','running'].includes(status.status))" @click="start">선택 파일 해시 계산 시작</button><p v-if="status" role="status">{{status.status}} · {{status.processed}}/{{status.total}} · 해시 {{status.hashed}} · 실패 {{status.failed}} · 취소 {{status.canceled}}</p><ul><li v-for="item in details" :key="item.fileId">{{item.fileId}} · {{item.status}} {{item.errorCode??''}}</li></ul><button v-if="detailCursor&&status&&!status.needsRecovery&&!['queued','running'].includes(status.status)" type="button" :disabled="busy" @click="moreDetails">다음 파일 상태</button><button v-if="status&&['queued','running'].includes(status.status)" type="button" :disabled="busy" @click="cancel">{{status.needsRecovery?'중단 해시 작업 정리':'해시 작업 취소'}}</button><button v-if="jobId" type="button" :disabled="busy" @click="compare()">저장된 해시 후보 비교</button><p v-if="stale">변경·누락 등 재확인 필요 {{stale}}개는 후보에서 제외했습니다.</p><ol><li v-for="group in groups" :key="group.sha256"><p>SHA-256 {{group.sha256}} · {{group.size}}바이트 · 파일{{group.fileCount}}개</p><ul><li v-for="file in group.files" :key="file.fileId">{{file.name}} · 실제 파일 {{file.fileId}} · 논리 소속{{file.logicalAssetCount}}개 ({{file.logicalAssetIds.join(', ')}})</li></ul></li></ol><button v-if="groupCursor||fileCursor" type="button" :disabled="busy" @click="compare(true)">다음 후보/파일 보기</button><p v-if="message" role="status">{{message}}</p></details></template>
